package com.trampolim.api.radar;
import java.util.*;import org.springframework.web.bind.annotation.*;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;
@RestController
public class RadarInvalidationController {
 private final JdbcTemplate jdbc;private final RadarBridge bridge;public RadarInvalidationController(@Qualifier("jdbcTemplate")JdbcTemplate jdbc,RadarBridge bridge){this.jdbc=jdbc;this.bridge=bridge;}
 public record Invalidation(List<UUID> receipts){}
 @PostMapping("/api/integrations/radar/invalidate")@Transactional("oportunidadesTransactionManager")public Map<String,Object> invalidate(@RequestHeader(name="X-Trampolim-Bridge",required=false)String key,@RequestBody Invalidation input){bridge.authorize(key);if(input==null||input.receipts()==null||input.receipts().isEmpty()||input.receipts().size()>100||input.receipts().stream().anyMatch(Objects::isNull))RadarModel.bad("Referências inválidas.");String ids=String.join(",",Collections.nCopies(input.receipts().size(),"?"));var args=input.receipts().toArray();jdbc.update("DELETE FROM radar_match_cache WHERE user_id IN (SELECT user_id FROM candidate_skill_evidence WHERE receipt_id IN ("+ids+"))",args);jdbc.update("UPDATE future_preparation_snapshots SET checked_at=TIMESTAMPTZ '1970-01-01 00:00:00+00',ready=FALSE WHERE interest_id IN (SELECT i.id FROM future_talent_interests i JOIN candidate_skill_evidence e ON e.user_id=i.user_id WHERE e.receipt_id IN ("+ids+"))",args);jdbc.update("UPDATE future_talent_interests SET refresh_after=CURRENT_TIMESTAMP WHERE user_id IN (SELECT user_id FROM candidate_skill_evidence WHERE receipt_id IN ("+ids+"))",args);return Map.of("status","INVALIDATED");}
}
